#!/usr/bin/env node
/*
 * grid14 step-by-step traffic simulator  (Node.js, standard library only)
 *
 * Implements the GRID-14 packet model (grid14_v1.pdf, Sections 1-7, Figures 1-4).
 * All numeric constants were read from the figures; see spec_values.md.
 *
 * Language/runtime: JavaScript on Node.js (see `node --version`). No external
 * modules are required; only the Node core modules 'fs', 'os', 'child_process'
 * (the last two only for the parallel sweep driver) are used.
 *
 * Modes (see dispatch at bottom):
 *   node simulator.js baseline
 *   node simulator.js config <cycle> <plan> <lead|lag> <o0..o8>   (offsets in seconds)
 *   node simulator.js trace  <outfile>                            (baseline AM trace)
 *   node simulator.js sweepchunk <prog> <offStart> <offEnd> <baseTTS>  (prints JSON)
 *   node simulator.js worker                                      (IPC worker for sweep.js)
 */
'use strict';
const MASK = 0x7fffffff;

// ---- sides, movements, phases ----
const Nn = 0, Ee = 1, Ss = 2, Ww = 3;
const opp = d => (d + 2) & 3;
const Lm = 0, Tm = 1, Rm = 2;
const PA = 0, PB = 1, PC = 2, PD = 3;

// destSide[approach][movement]
const destSide = [
  [Ee, Ss, Ww], // N: L->E,T->S,R->W
  [Ss, Ww, Nn], // E: L->S,T->W,R->N
  [Ww, Nn, Ee], // S: L->W,T->N,R->E
  [Nn, Ee, Ss], // W: L->N,T->E,R->S
];
function reqPhase(appr, mov) {
  const vertical = (appr === Nn || appr === Ss);
  if (mov === Lm) return vertical ? PB : PD;
  return vertical ? PA : PC;
}

// ---- geometry (Figure 1) ----
const hblock = [[32, 26], [22, 36], [28, 24]];     // [row][mincol]
const vblock = [[30, 24, 27], [20, 34, 21]];       // [minrow][col]
const inboundLen = [38, 44, 36, 41, 35, 43, 39, 37, 45, 42, 40, 36];
// terminal -> [intersection, approach side]
const terminalEntry = [
  [0, Nn], [1, Nn], [2, Nn], [2, Ee], [5, Ee], [8, Ee],
  [6, Ss], [7, Ss], [8, Ss], [0, Ww], [3, Ww], [6, Ww],
];

const DEMAND = {
  AM:    [208, 266, 182, 234, 195, 254, 221, 176, 273, 247, 202, 228],
  PM:    [221, 176, 273, 247, 202, 228, 208, 266, 182, 234, 195, 254],
  EVENT: [208, 266, 182, 234, 312, 254, 221, 176, 273, 395, 202, 228],
};
const CYCLES = [60, 72, 84, 96, 108, 120];
// greens[cycle][plan-1] = [gA,gB,gC,gD]
const GREENS = {
  60:  [[18,8,18,8],[22,6,18,6],[16,7,22,7],[20,9,16,7],[16,7,20,9],[21,5,21,5]],
  72:  [[22,10,22,10],[27,8,22,7],[20,9,27,8],[25,11,20,8],[20,8,25,11],[26,6,26,6]],
  84:  [[26,12,26,12],[32,9,26,9],[23,11,32,10],[29,14,23,10],[23,11,29,13],[31,7,31,7]],
  96:  [[30,14,30,14],[37,11,30,10],[27,12,37,12],[34,15,27,12],[27,12,34,15],[36,8,36,8]],
  108: [[34,16,34,16],[42,12,34,12],[30,14,42,14],[38,18,30,14],[30,14,38,18],[40,10,40,10]],
  120: [[39,17,39,17],[48,13,38,13],[34,15,48,15],[43,20,34,15],[34,15,43,20],[45,11,45,11]],
};

function neighbor(J, side) {
  const r = (J / 3) | 0, c = J % 3;
  if (side === Nn) return r > 0 ? ['I', (r - 1) * 3 + c] : ['T', c];
  if (side === Ee) return c < 2 ? ['I', r * 3 + c + 1] : ['T', 3 + r];
  if (side === Ss) return r < 2 ? ['I', (r + 1) * 3 + c] : ['T', 6 + c];
  return c > 0 ? ['I', r * 3 + c - 1] : ['T', 9 + r];
}
function blockLen(i, j) {
  const ri = (i / 3) | 0, ci = i % 3, rj = (j / 3) | 0, cj = j % 3;
  if (ri === rj) return hblock[ri][Math.min(ci, cj)];
  return vblock[Math.min(ri, rj)][ci];
}

// ---- network ----
let NET = null;
function buildNet() {
  const linkLen = [];
  const keyMap = new Map();
  const inv = [];
  const outLink = Array.from({ length: 9 }, () => [0, 0, 0, 0]);
  const inLink = Array.from({ length: 9 }, () => [0, 0, 0, 0]);
  function getlink(fk, tk, len) {
    const k = fk + '>' + tk;
    let id = keyMap.get(k);
    if (id === undefined) { id = linkLen.length; linkLen.push(len); keyMap.set(k, id); inv.push(k); }
    return id;
  }
  for (let J = 0; J < 9; J++) {
    for (const side of [Nn, Ee, Ss, Ww]) {
      const [typ, nb] = neighbor(J, side);
      if (typ === 'I') {
        const ln = blockLen(J, nb);
        outLink[J][side] = getlink('I' + J, 'I' + nb, ln);
        inLink[J][side] = getlink('I' + nb, 'I' + J, ln);
      } else {
        outLink[J][side] = getlink('I' + J, 'T' + nb, 10);
        inLink[J][side] = getlink('T' + nb, 'I' + J, inboundLen[nb]);
      }
    }
  }
  const nL = linkLen.length;
  const base = new Int32Array(nL);
  let acc = 0;
  for (let i = 0; i < nL; i++) { base[i] = acc; acc += linkLen[i]; }
  return {
    linkLen: Int32Array.from(linkLen), base, totalCells: acc,
    outLink, inLink, nLinks: nL, inv,
  };
}
function getNet() { if (!NET) NET = buildNet(); return NET; }

// ---- scenario precompute: creation schedule + routes (flattened) ----
const SCEN = {};
function buildScenario(scn) {
  if (SCEN[scn]) return SCEN[scn];
  const net = getNet();
  const demand = DEMAND[scn];
  // creation schedule
  const xs = new Int32Array(12);
  for (let k = 0; k < 12; k++) xs[k] = (1000 + 17 * k) & MASK;
  const gArr = []; const originArr = [];
  const createdMask = new Int32Array(3600);
  const termVidsLists = Array.from({ length: 12 }, () => []);
  let vid = 0;
  for (let t = 0; t < 3600; t++) {
    let mask = 0;
    for (let k = 0; k < 12; k++) {
      let x = xs[k];
      x = (Number((BigInt(1103515245) * BigInt(x) + 12345n) & BigInt(MASK)));
      xs[k] = x;
      if (((x >>> 8) % 3600) < demand[k]) {
        gArr.push(t); originArr.push(k); termVidsLists[k].push(vid);
        mask |= (1 << k); vid++;
      }
    }
    createdMask[t] = mask;
  }
  const nVeh = vid;
  const g = Int32Array.from(gArr);
  const origin = Int32Array.from(originArr);
  // termVids flat
  const termOff = new Int32Array(13);
  for (let k = 0; k < 12; k++) termOff[k + 1] = termOff[k] + termVidsLists[k].length;
  const termVids = new Int32Array(nVeh);
  for (let k = 0; k < 12; k++) {
    const lst = termVidsLists[k]; const off = termOff[k];
    for (let i = 0; i < lst.length; i++) termVids[off + i] = lst[i];
  }
  // routes
  const rStart = new Int32Array(nVeh + 1);
  const linkTmp = []; const interTmp = []; const reqTmp = []; const apprTmp = []; const movTmp = [];
  for (let v = 0; v < nVeh; v++) {
    rStart[v] = linkTmp.length;
    let y = Number((BigInt(2654435761) * BigInt(v) + 12345n) & BigInt(MASK));
    let [J, appr] = terminalEntry[origin[v]];
    let cur = net.inLink[J][appr];
    let guard = 0;
    for (;;) {
      if (++guard > 100000) throw new Error('route loop vid ' + v);
      linkTmp.push(cur);
      y = Number((BigInt(1103515245) * BigInt(y) + 12345n) & BigInt(MASK));
      const r = (y >>> 16) % 100;
      const vertical = (appr === Nn || appr === Ss);
      const Lthr = vertical ? 20 : 10;
      const mov = r < Lthr ? Lm : (r >= 85 ? Rm : Tm);
      interTmp.push(J); reqTmp.push(reqPhase(appr, mov)); apprTmp.push(appr); movTmp.push(mov);
      const ds = destSide[appr][mov];
      const [typ, nb] = neighbor(J, ds);
      if (typ === 'T') {
        linkTmp.push(net.outLink[J][ds]);
        interTmp.push(-1); reqTmp.push(-1); apprTmp.push(-1); movTmp.push(-1);
        break;
      } else {
        cur = net.outLink[J][ds];
        J = nb; appr = opp(ds);
      }
    }
  }
  rStart[nVeh] = linkTmp.length;
  const S = {
    nVeh, g, origin, createdMask, termVids, termOff,
    rStart, rLink: Int32Array.from(linkTmp), rInter: Int32Array.from(interTmp),
    rReq: Int32Array.from(reqTmp), rAppr: Int32Array.from(apprTmp), rMov: Int32Array.from(movTmp),
  };
  SCEN[scn] = S;
  return S;
}

// phase-at-local-time array
function phaseAtArray(cycle, plan, order) {
  const g = GREENS[cycle][plan - 1];
  const seq = (order === 'lead')
    ? [[PA, g[0]], [PB, g[1]], [PC, g[2]], [PD, g[3]]]
    : [[PB, g[1]], [PA, g[0]], [PD, g[3]], [PC, g[2]]];
  const arr = new Int32Array(cycle).fill(-1);
  let pos = 0;
  for (const [ph, gg] of seq) { for (let i = 0; i < gg; i++) arr[pos + i] = ph; pos += gg + 2; }
  return arr;
}

// ---- reusable run buffers (sized to the current scenario) ----
let BUF = { cells: 0, nVeh: 0, occ: null, seg: null, cell: null, active: null, dec: null,
            qHead: null, qTail: null, enter: null };
function ensureBuffers(net, nVeh) {
  if (BUF.cells !== net.totalCells || BUF.nVeh < nVeh) {
    BUF.cells = net.totalCells; BUF.nVeh = nVeh;
    BUF.occ = new Int32Array(net.totalCells);
    BUF.seg = new Int32Array(nVeh);
    BUF.cell = new Int32Array(nVeh);
    BUF.active = new Int32Array(net.totalCells + 16);
    BUF.dec = new Int8Array(net.totalCells + 16);
    BUF.qHead = new Int32Array(12);
    BUF.qTail = new Int32Array(12);
    BUF.enter = new Int32Array(12);
  }
}

/*
 * Core run.  offsetsSec: Int32Array/array length 9 (offsets in seconds).
 * trace: null, or an object with push-able arrays {C,X,D,P,SUM} to record.
 * Returns {tts, gridlock, end, created, departed}.
 */
function runScenario(net, S, cycle, plan, order, offsetsSec, trace) {
  const arr = phaseAtArray(cycle, plan, order);
  const nVeh = S.nVeh;
  ensureBuffers(net, nVeh);
  const occ = BUF.occ; occ.fill(-1);
  const seg = BUF.seg, cell = BUF.cell, active = BUF.active, dec = BUF.dec;
  const qHead = BUF.qHead, qTail = BUF.qTail, enter = BUF.enter;
  qHead.fill(0); qTail.fill(0);
  const base = net.base, linkLen = net.linkLen;
  const rStart = S.rStart, rLink = S.rLink, rInter = S.rInter, rReq = S.rReq;
  const g = S.g, createdMask = S.createdMask, termVids = S.termVids, termOff = S.termOff;
  const gph = new Int32Array(9);

  let nActive = 0, waiting = 0, innet = 0, departed = 0, created = 0, tts = 0;
  let end = -1;
  const tracing = !!trace;

  for (let t = 0; ; t++) {
    // (1) creation
    if (t < 3600) {
      const mask = createdMask[t];
      if (mask) for (let k = 0; k < 12; k++) if (mask & (1 << k)) {
        qTail[k]++; waiting++; created++;
        if (tracing) trace.C.push(t + ' ' + termVids[termOff[k] + qTail[k] - 1] + ' ' + k);
      }
    }
    // green phase per intersection
    const tmod = t % cycle;
    for (let j = 0; j < 9; j++) { let tau = tmod - offsetsSec[j]; if (tau < 0) tau += cycle; gph[j] = arr[tau]; }

    // (2a) decide for active vehicles
    for (let i = 0; i < nActive; i++) {
      const v = active[i];
      const s = seg[v]; const st = rStart[v] + s; const lk = rLink[st];
      const Lb = base[lk]; const Ln = linkLen[lk]; const cc = cell[v];
      let d = 0;
      if (s === rStart[v + 1] - rStart[v] - 1) {        // final (outbound) segment
        if (cc === Ln - 1) d = 3;                        // EXIT
        else if (occ[Lb + cc + 1] === -1) d = 1;         // ADV
      } else {
        if (cc < Ln - 1) { if (occ[Lb + cc + 1] === -1) d = 1; }
        else {
          const J = rInter[st];
          if (gph[J] === rReq[st]) { if (occ[base[rLink[st + 1]]] === -1) d = 2; }
        }
      }
      dec[i] = d;
    }
    // queue-entry decisions
    let nEnter = 0;
    for (let k = 0; k < 12; k++) {
      if (qHead[k] < qTail[k]) {
        const head = termVids[termOff[k] + qHead[k]];
        if (occ[base[rLink[rStart[head]]]] === -1) enter[nEnter++] = head;
      }
    }

    // (2b) apply
    let w = 0;
    for (let i = 0; i < nActive; i++) {
      const v = active[i]; const d = dec[i];
      if (d === 0) { active[w++] = v; continue; }
      const s = seg[v]; const st = rStart[v] + s; const lk = rLink[st]; const Lb = base[lk]; const cc = cell[v];
      if (d === 1) {                       // ADV
        occ[Lb + cc] = -1; occ[Lb + cc + 1] = v; cell[v] = cc + 1; active[w++] = v;
      } else if (d === 2) {                // CROSS
        occ[Lb + cc] = -1;
        const nl = rLink[st + 1]; occ[base[nl]] = v;
        if (tracing) trace.X.push(t + ' ' + v + ' ' + rInter[st] + ' ' + S.rAppr[st] + ' ' + S.rMov[st] + ' ' + lk + ' ' + nl);
        seg[v] = s + 1; cell[v] = 0; active[w++] = v;
      } else {                             // EXIT (d===3)
        occ[Lb + cc] = -1; departed++; innet--; tts += t - g[v] + 1;
        if (tracing) trace.D.push(t + ' ' + v);
      }
    }
    for (let e = 0; e < nEnter; e++) {
      const v = enter[e]; const k = S.origin[v];
      occ[base[rLink[rStart[v]]]] = v;
      seg[v] = 0; cell[v] = 0; innet++; qHead[k]++; waiting--;
      active[w++] = v;
    }
    nActive = w;

    if (tracing) {
      for (let i = 0; i < nActive; i++) {
        const v = active[i]; trace.P.push(t + ' ' + v + ' ' + rLink[rStart[v] + seg[v]] + ' ' + cell[v]);
      }
      trace.SUM.push(t + ' ' + created + ' ' + waiting + ' ' + innet + ' ' + departed);
    }

    if ((t >= 3599 && waiting === 0 && innet === 0) || t === 7199) { end = t; break; }
  }

  const gridlock = (end === 7199 && (waiting + innet) > 0);
  if (end === 7199) {
    for (let i = 0; i < nActive; i++) tts += 7200 - g[active[i]];           // in network
    for (let k = 0; k < 12; k++) for (let idx = qHead[k]; idx < qTail[k]; idx++) tts += 7200 - g[termVids[termOff[k] + idx]]; // waiting
  }
  return { tts, gridlock, end, created, departed };
}

function runConfig(cycle, plan, order, offsetsSec) {
  const net = getNet();
  const res = {};
  for (const scn of ['AM', 'PM', 'EVENT']) {
    const S = buildScenario(scn);
    res[scn] = runScenario(net, S, cycle, plan, order, offsetsSec, null);
  }
  const total = res.AM.tts + res.PM.tts + res.EVENT.tts;
  const gl = res.AM.gridlock || res.PM.gridlock || res.EVENT.gridlock;
  return { res, total, gl };
}

// ---- sweep over offset combos for one program (cycle,plan,order) ----
// prog index: cycle(0..5)*12 + plan(0..5)*2 + order(0..1)
function progDecode(prog) {
  const order = (prog & 1) ? 'lag' : 'lead';
  const plan = (((prog >> 1) % 6)) + 1;
  const cycle = CYCLES[(prog / 12) | 0];
  return { cycle, plan, order };
}
function sweepChunk(prog, offStart, offEnd, baseTTS) {
  const net = getNet();
  const { cycle, plan, order } = progDecode(prog);
  const SA = buildScenario('AM'), SP = buildScenario('PM'), SE = buildScenario('EVENT');
  const q = cycle / 4;
  const offv = new Int32Array(9);
  let sumTTS = 0, countBelow = 0, countGridlock = 0, nSim = 0;
  // best key (total,cycle,plan,orderNum,o0..o8) minimized
  let best = null;
  const orderNum = (order === 'lag') ? 1 : 0;
  for (let combo = offStart; combo < offEnd; combo++) {
    let c = combo;
    for (let j = 0; j < 9; j++) { offv[j] = (c & 3) * q; c >>= 2; }
    const rAM = runScenario(net, SA, cycle, plan, order, offv, null);
    const rPM = runScenario(net, SP, cycle, plan, order, offv, null);
    const rEV = runScenario(net, SE, cycle, plan, order, offv, null);
    const total = rAM.tts + rPM.tts + rEV.tts;
    const gl = rAM.gridlock || rPM.gridlock || rEV.gridlock;
    sumTTS += total; nSim++;
    if (total < baseTTS) countBelow++;
    if (gl) countGridlock++;
    if (best === null || total < best.total) {
      const offIdx = []; let cc = combo; for (let j = 0; j < 9; j++) { offIdx.push(cc & 3); cc >>= 2; }
      best = { total, cycle, plan, orderNum, offIdx, gl };
    }
  }
  return { prog, cycle, plan, order, offStart, offEnd, sumTTS, countBelow, countGridlock, nSim, best };
}

// ---- trace emission (baseline AM) ----
function emitTrace(outfile) {
  const fs = require('fs');
  const net = getNet();
  const S = buildScenario('AM');
  const cycle = 84, plan = 1, order = 'lead';
  const offsetsSec = new Int32Array(9); // all 0
  const trace = { C: [], X: [], D: [], P: [], SUM: [] };
  const r = runScenario(net, S, cycle, plan, order, offsetsSec, trace);
  const out = fs.createWriteStream(outfile);
  out.write('# grid14 baseline AM trace\n');
  out.write('CFG cycle=84 plan=1 order=lead scenario=AM offsets=0,0,0,0,0,0,0,0,0\n');
  out.write('# link lengths: ' + Array.from(net.linkLen).join(',') + '\n');
  out.write('# totalcells=' + net.totalCells + ' nveh=' + S.nVeh + ' end=' + r.end + ' tts=' + r.tts + '\n');
  out.write('# record types: C=create <t vid term>  X=crossing <t vid inter appr mov fromlink tolink>\n');
  out.write('#               D=depart <t vid>  P=position-at-end-of-step <t vid link cell>  SUM <t created waiting innet departed>\n');
  for (const l of trace.C) out.write('C ' + l + '\n');
  for (const l of trace.X) out.write('X ' + l + '\n');
  for (const l of trace.D) out.write('D ' + l + '\n');
  for (const l of trace.P) out.write('P ' + l + '\n');
  for (const l of trace.SUM) out.write('SUM ' + l + '\n');
  out.end();
  return new Promise(res => out.on('finish', () => res(r)));
}

// ---- CLI / worker dispatch ----
function main() {
  const argv = process.argv.slice(2);
  const mode = argv[0];
  if (mode === 'baseline') {
    const net = getNet();
    process.stdout.write('total_cells=' + net.totalCells + ' n_links=' + net.nLinks + '\n');
    const { res, total, gl } = runConfig(84, 1, 'lead', new Int32Array(9));
    process.stdout.write('BASELINE C=84 plan=1 lead offsets=0\n');
    for (const scn of ['AM', 'PM', 'EVENT'])
      process.stdout.write('  ' + scn + ' TTS=' + res[scn].tts + ' end=' + res[scn].end +
        ' created=' + res[scn].created + ' departed=' + res[scn].departed + '\n');
    process.stdout.write('  TOTAL=' + total + ' gridlock=' + gl + '\n');
  } else if (mode === 'config') {
    const cycle = +argv[1], plan = +argv[2], order = argv[3];
    const offs = Int32Array.from(argv.slice(4, 13).map(Number));
    const { res, total, gl } = runConfig(cycle, plan, order, offs);
    process.stdout.write('config C=' + cycle + ' plan=' + plan + ' ' + order + ' offsets=' + Array.from(offs).join(',') + '\n');
    for (const scn of ['AM', 'PM', 'EVENT'])
      process.stdout.write('  ' + scn + ' TTS=' + res[scn].tts + ' end=' + res[scn].end + ' gridlock=' + res[scn].gridlock + '\n');
    process.stdout.write('  TOTAL=' + total + ' gridlock=' + gl + '\n');
  } else if (mode === 'trace') {
    emitTrace(argv[1] || 'baseline_am_trace.txt').then(r => {
      process.stdout.write('trace written: end=' + r.end + ' tts=' + r.tts + '\n');
    });
  } else if (mode === 'sweepchunk') {
    const prog = +argv[1], offStart = +argv[2], offEnd = +argv[3], baseTTS = +argv[4];
    const res = sweepChunk(prog, offStart, offEnd, baseTTS);
    process.stdout.write(JSON.stringify(res) + '\n');
  } else if (mode === 'worker') {
    // IPC worker for sweep.js
    getNet(); buildScenario('AM'); buildScenario('PM'); buildScenario('EVENT');
    process.send({ ready: true });
    process.on('message', (msg) => {
      if (msg.stop) { process.exit(0); }
      const res = sweepChunk(msg.prog, msg.offStart, msg.offEnd, msg.baseTTS);
      process.send({ done: true, taskId: msg.taskId, res });
    });
  } else {
    process.stderr.write('unknown mode: ' + mode + '\n');
    process.exit(1);
  }
}
main();

