      const ds = destSide[appr][mov]; const [typ, nb] = neighbor(J, ds);
      if (typ === 'T') { linkTmp.push(net.outLink[J][ds]); interTmp.push(-1); reqTmp.push(-1); apprTmp.push(-1); movTmp.push(-1); break; }
