// ---- selftest: full vs fast ----
function selftest() {
  const net = getNet();
  const scns = ['AM', 'PM', 'EVENT'].map(buildScenario);
  const names = ['AM', 'PM', 'EVENT'];
  let rng = 12345;
  const rnd = () => (rng = (1103515245 * rng + 12345) & MASK) / 2147483648;
  const cases = [];
