const destSide = [
  [Ee, Ss, Ww], // N: L->E,T->S,R->W
  [Ss, Ww, Nn], // E: L->S,T->W,R->N
  [Ww, Nn, Ee], // S: L->W,T->N,R->E
  [Nn, Ee, Ss], // W: L->N,T->E,R->S
