  const linkTmp = []; const interTmp = []; const reqTmp = []; const apprTmp = []; const movTmp = [];
  for (let v = 0; v < nVeh; v++) {
    rStart[v] = linkTmp.length;
    let y = Number((BigInt(2654435761) * BigInt(v) + 12345n) & BigInt(MASK));
    let [J, appr] = terminalEntry[origin[v]];
    let cur = net.inLink[J][appr];
    let guard = 0;
    for (;;) {
      if (++guard > 100000) throw new Error('route loop vid ' + v);
      linkTmp.push(cur);
      y = Number((BigInt(1103515245) * BigInt(y) + 12345n) & BigInt(MASK));
      const r = (y >>> 16) % 100;
      const vertical = (appr === Nn || appr === Ss);
      const Lthr = vertical ? 20 : 10;
      const mov = r < Lthr ? Lm : (r >= 85 ? Rm : Tm);
      interTmp.push(J); reqTmp.push(reqPhase(appr, mov)); apprTmp.push(appr); movTmp.push(mov);
      const ds = destSide[appr][mov];
      const [typ, nb] = neighbor(J, ds);
      if (typ === 'T') {
        linkTmp.push(net.outLink[J][ds]);
        interTmp.push(-1); reqTmp.push(-1); apprTmp.push(-1); movTmp.push(-1);
        break;
