    nVeh, g, origin, createdMask, termVids, termOff,
    rStart, rLink: Int32Array.from(linkTmp), rInter: Int32Array.from(interTmp),
    rReq: Int32Array.from(reqTmp), rAppr: Int32Array.from(apprTmp), rMov: Int32Array.from(movTmp),
