  if (BUF.cells !== net.totalCells || BUF.nVeh < nVeh) {
    BUF.cells = net.totalCells; BUF.nVeh = nVeh;
    BUF.occ = new Int32Array(net.totalCells);
    BUF.seg = new Int32Array(nVeh);
    BUF.cell = new Int32Array(nVeh);
    BUF.active = new Int32Array(net.totalCells + 16);
    BUF.dec = new Int8Array(net.totalCells + 16);
