  for (const l of trace.C) out.write('C ' + l + '\n');
  for (const l of trace.X) out.write('X ' + l + '\n');
  for (const l of trace.D) out.write('D ' + l + '\n');
  for (const l of trace.P) out.write('P ' + l + '\n');
  for (const l of trace.SUM) out.write('SUM ' + l + '\n');
