    const rAM = runFast(net, SA, cycle, plan, order, offv, null);
    const rPM = runFast(net, SP, cycle, plan, order, offv, null);
    const rEV = runFast(net, SE, cycle, plan, order, offv, null);
    const total = rAM.tts + rPM.tts + rEV.tts;
    const gl = rAM.gridlock || rPM.gridlock || rEV.gridlock;
