let B = { cells: -1, nVeh: -1 };
function ensureBuffers(net, nVeh) {
  if (B.cells !== net.totalCells || B.nVeh < nVeh) {
    B.cells = net.totalCells; B.nVeh = nVeh;
    B.occ = new Int32Array(net.totalCells);
    B.seg = new Int32Array(nVeh); B.cell = new Int32Array(nVeh);
    const cap = net.totalCells + 16;
    B.cand = new Int32Array(cap); B.candDec = new Int8Array(cap); B.nextCand = new Int32Array(cap);
    B.stamp = new Float64Array(nVeh); B.stamp.fill(-1);
    B.qHead = new Int32Array(12); B.qTail = new Int32Array(12); B.enter = new Int32Array(12);
