  out.write('CFG cycle=84 plan=1 order=lead scenario=AM offsets=0,0,0,0,0,0,0,0,0\n');
  out.write('# linklen ' + Array.from(net.linkLen).join(',') + '\n');
  out.write('# meta totalcells=' + net.totalCells + ' nveh=' + S.nVeh + ' end=' + r.end + ' tts=' + r.tts + '\n');
  out.write('# C <t vid term> | X <t vid inter appr mov fromlink tolink> | D <t vid> | P <t vid link cell> | SUM <t created waiting innet departed>\n');
  const chunks = [];
  for (const l of trace.C) chunks.push('C ' + l);
  for (const l of trace.X) chunks.push('X ' + l);
  for (const l of trace.D) chunks.push('D ' + l);
  for (const l of trace.P) chunks.push('P ' + l);
  for (const l of trace.SUM) chunks.push('SUM ' + l);
