  cases.push([84, 1, 'lead', [0,21,42,0,21,42,0,21,42]]);
  cases.push([84, 1, 'lag',  [0,0,0,0,0,0,0,0,0]]);
  cases.push([60, 1, 'lead', [0,0,0,0,0,0,0,0,0]]);
