    const cycle = CYCLES[(rnd() * 6) | 0];
    const plan = 1 + ((rnd() * 6) | 0);
    const order = rnd() < 0.5 ? 'lead' : 'lag';
    const q = cycle / 4; const offs = [];
    for (let j = 0; j < 9; j++) offs.push(((rnd() * 4) | 0) * q);
    cases.push([cycle, plan, order, offs]);
  }
  let bad = 0;
  for (const [cycle, plan, order, offs] of cases) {
    const off = Int32Array.from(offs);
    for (let s = 0; s < 3; s++) {
      const a = runFull(net, scns[s], cycle, plan, order, off);
      const b = runFast(net, scns[s], cycle, plan, order, off);
      if (a.tts !== b.tts || a.gridlock !== b.gridlock || a.end !== b.end) {
        bad++; process.stdout.write('MISMATCH ' + names[s] + ' C=' + cycle + ' plan=' + plan + ' ' + order + ' offs=' + offs + ' full=' + JSON.stringify(a) + ' fast=' + JSON.stringify(b) + '\n');
      }
    }
  }
  process.stdout.write('selftest: ' + cases.length + ' configs x3 scenarios; mismatches=' + bad + '\n');
  if (bad) process.exit(1);
}

// ---- dispatch ----
function main() {
  const argv = process.argv.slice(2); const mode = argv[0];
  if (mode === 'baseline') {
    const net = getNet();
    process.stdout.write('total_cells=' + net.totalCells + ' n_links=' + net.nLinks + '\n');
    const { res, total, gl } = runConfig(84, 1, 'lead', new Int32Array(9), runFast);
    process.stdout.write('BASELINE C=84 plan=1 lead offsets=0\n');
    for (const scn of ['AM', 'PM', 'EVENT']) process.stdout.write('  ' + scn + ' TTS=' + res[scn].tts + ' end=' + res[scn].end + ' created=' + res[scn].created + ' departed=' + res[scn].departed + '\n');
    process.stdout.write('  TOTAL=' + total + ' gridlock=' + gl + '\n');
  } else if (mode === 'config') {
    const cycle = +argv[1], plan = +argv[2], order = argv[3];
    const offs = Int32Array.from(argv.slice(4, 13).map(Number));
    const eng = argv[13] === 'full' ? runFull : runFast;
    const { res, total, gl } = runConfig(cycle, plan, order, offs, eng);
    process.stdout.write('config C=' + cycle + ' plan=' + plan + ' ' + order + ' offsets=' + Array.from(offs).join(',') + '\n');
    for (const scn of ['AM', 'PM', 'EVENT']) process.stdout.write('  ' + scn + ' TTS=' + res[scn].tts + ' end=' + res[scn].end + ' gridlock=' + res[scn].gridlock + '\n');
    process.stdout.write('  TOTAL=' + total + ' gridlock=' + gl + '\n');
  } else if (mode === 'trace') {
    emitTrace(argv[1] || 'baseline_am_trace.txt').then(r => process.stdout.write('trace written: end=' + r.end + ' tts=' + r.tts + '\n'));
  } else if (mode === 'selftest') {
    selftest();
  } else if (mode === 'sweepchunk') {
    const prog = +argv[1], offStart = +argv[2], offEnd = +argv[3], baseTTS = +argv[4];
    process.stdout.write(JSON.stringify(sweepChunk(prog, offStart, offEnd, baseTTS)) + '\n');
  } else if (mode === 'worker') {
    getNet(); buildScenario('AM'); buildScenario('PM'); buildScenario('EVENT');
    process.send({ ready: true });
    process.on('message', (msg) => { if (msg.stop) process.exit(0); process.send({ done: true, taskId: msg.taskId, res: sweepChunk(msg.prog, msg.offStart, msg.offEnd, msg.baseTTS) }); });
  } else { process.stderr.write('unknown mode: ' + mode + '\n'); process.exit(1); }
}
module.exports = { getNet, buildScenario, runFast, runFull, runConfig, phaseAtArray, sweepChunk, progDecode, CYCLES };
if (require.main === module) main();

