  const nVeh = S.nVeh; ensureBuffers(net, nVeh);
  const occ = B.occ; occ.fill(-1);
  const seg = B.seg, cell = B.cell, active = B.active, dec = B.candDec, enter = B.enter;
  const qHead = B.qHead, qTail = B.qTail;
  qHead.fill(0); qTail.fill(0);
  const base = net.base, linkLen = net.linkLen;
  const rStart = S.rStart, rLink = S.rLink, rInter = S.rInter, rReq = S.rReq, g = S.g;
  const createdMask = S.createdMask, termVids = S.termVids, termOff = S.termOff, origin = S.origin;
  const gph = new Int32Array(9);
  let nActive = 0, waiting = 0, innet = 0, departed = 0, created = 0, tts = 0, end = -1;
  for (let t = 0; ; t++) {
    if (t < 3600) { const mask = createdMask[t]; if (mask) for (let k = 0; k < 12; k++) if (mask & (1 << k)) { qTail[k]++; waiting++; created++; } }
    const tmod = t % cycle;
    for (let j = 0; j < 9; j++) { let tau = tmod - offsetsSec[j]; if (tau < 0) tau += cycle; gph[j] = arr[tau]; }
    for (let i = 0; i < nActive; i++) {
      const v = active[i]; const s = seg[v]; const st = rStart[v] + s; const lk = rLink[st];
      const Lb = base[lk]; const Ln = linkLen[lk]; const cc = cell[v]; let d = 0;
      if (s === rStart[v + 1] - rStart[v] - 1) { if (cc === Ln - 1) d = 3; else if (occ[Lb + cc + 1] === -1) d = 1; }
      else if (cc < Ln - 1) { if (occ[Lb + cc + 1] === -1) d = 1; }
      else { const J = rInter[st]; if (gph[J] === rReq[st] && occ[base[rLink[st + 1]]] === -1) d = 2; }
      dec[i] = d;
    }
    let nEnter = 0;
    for (let k = 0; k < 12; k++) if (qHead[k] < qTail[k]) { const head = termVids[termOff[k] + qHead[k]]; if (occ[base[rLink[rStart[head]]]] === -1) enter[nEnter++] = head; }
    let w = 0;
    for (let i = 0; i < nActive; i++) {
      const v = active[i]; const d = dec[i];
      if (d === 0) { active[w++] = v; continue; }
      const s = seg[v]; const st = rStart[v] + s; const lk = rLink[st]; const Lb = base[lk]; const cc = cell[v];
      if (d === 1) { occ[Lb + cc] = -1; occ[Lb + cc + 1] = v; cell[v] = cc + 1; active[w++] = v; }
      else if (d === 2) { occ[Lb + cc] = -1; const nl = rLink[st + 1]; occ[base[nl]] = v; seg[v] = s + 1; cell[v] = 0; active[w++] = v; }
      else { occ[Lb + cc] = -1; departed++; innet--; tts += t - g[v] + 1; }
    }
    for (let e = 0; e < nEnter; e++) { const v = enter[e]; const k = origin[v]; occ[base[rLink[rStart[v]]]] = v; seg[v] = 0; cell[v] = 0; innet++; qHead[k]++; waiting--; active[w++] = v; }
