  }
  const gridlock = (end === 7199 && (waiting + innet) > 0);
  if (end === 7199) {
    for (let i = 0; i < nActive; i++) tts += 7200 - g[active[i]];
    for (let k = 0; k < 12; k++) for (let idx = qHead[k]; idx < qTail[k]; idx++) tts += 7200 - g[termVids[termOff[k] + idx]];
