function runConfig(cycle, plan, order, offsetsSec, engine) {
  const net = getNet(); const run = engine || runFast; const res = {};
  for (const scn of ['AM', 'PM', 'EVENT']) res[scn] = run(net, buildScenario(scn), cycle, plan, order, offsetsSec);
