  const gl = res.AM.gridlock || res.PM.gridlock || res.EVENT.gridlock;
  return { res, total, gl };
}

// ---- sweep ----
function progDecode(prog) {
  const order = (prog & 1) ? 'lag' : 'lead';
  const plan = ((prog >> 1) % 6) + 1;
  const cycle = CYCLES[(prog / 12) | 0];
  return { cycle, plan, order };
}
function sweepChunk(prog, offStart, offEnd, baseTTS) {
  const net = getNet(); const { cycle, plan, order } = progDecode(prog);
  const SA = buildScenario('AM'), SP = buildScenario('PM'), SE = buildScenario('EVENT');
  const q = cycle / 4; const offv = new Int32Array(9);
