#!/usr/bin/env node
/*
 * Parallel driver for the full configuration-space sweep (Node.js stdlib only).
 * Forks N worker processes (simulator.js in 'worker' mode), hands out offset-range
 * chunks of each (cycle,plan,order) program, accumulates exact aggregates, and
 * checkpoints progress so partial results survive interruption.
 *
 * Env knobs (defaults = full exact sweep):
 *   NW=16           number of worker processes
 *   CHUNK=8192      offset combos per task (262144 per program)
 *   PLO=0 PHI=72    program index range [PLO,PHI)  (prog = cycleIdx*12 + (plan-1)*2 + order)
 *   OFFLO=0 OFFHI=262144   offset-combo range (for validation runs)
 *   BASE=4052648    baseline total TTS threshold for "below baseline"
 *   OUT=sweep_results.json   PROG=sweep_progress.json
 */
'use strict';
const { fork } = require('child_process');
const fs = require('fs');
const path = require('path');

const NW = parseInt(process.env.NW || '16');
const CHUNK = parseInt(process.env.CHUNK || '8192');
const PLO = parseInt(process.env.PLO || '0'), PHI = parseInt(process.env.PHI || '72');
const OFFLO = parseInt(process.env.OFFLO || '0'), OFFHI = parseInt(process.env.OFFHI || '262144');
const BASE = parseInt(process.env.BASE || '4052648');
const OUT = process.env.OUT || 'sweep_results.json';
const PROG = process.env.PROG || 'sweep_progress.json';
const CYC = [60, 72, 84, 96, 108, 120];

function progDecode(prog) { return { cycle: CYC[(prog / 12) | 0], plan: ((prog >> 1) % 6) + 1, order: (prog & 1) }; }

// build tasks
const tasks = [];
for (let prog = PLO; prog < PHI; prog++)
  for (let o = OFFLO; o < OFFHI; o += CHUNK) tasks.push({ prog, offStart: o, offEnd: Math.min(o + CHUNK, OFFHI) });
const TOTAL_TASKS = tasks.length;

// aggregates
let sumTTS = 0n, countBelow = 0, countGridlock = 0, nSim = 0;
const sumByCycle = Array(6).fill(0n), belowByCycle = Array(6).fill(0), glByCycle = Array(6).fill(0), nByCycle = Array(6).fill(0);
const sumByPlan = Array(6).fill(0n), belowByPlan = Array(6).fill(0), glByPlan = Array(6).fill(0), nByPlan = Array(6).fill(0);
const sumByOrder = [0n, 0n], belowByOrder = [0, 0], glByOrder = [0, 0], nByOrder = [0, 0];
let best = null;
let done = 0;
const t0 = Date.now();

function lessKey(a, b) {
  if (a.total !== b.total) return a.total < b.total;
  if (a.cycle !== b.cycle) return a.cycle < b.cycle;
  if (a.plan !== b.plan) return a.plan < b.plan;
  if (a.orderNum !== b.orderNum) return a.orderNum < b.orderNum;
  for (let j = 0; j < 9; j++) if (a.offIdx[j] !== b.offIdx[j]) return a.offIdx[j] < b.offIdx[j];
  return false;
}
function accumulate(res) {
  const s = BigInt(res.sumTTS);
  sumTTS += s; countBelow += res.countBelow; countGridlock += res.countGridlock; nSim += res.nSim;
  const { cycle, plan, order } = progDecode(res.prog);
  const ci = CYC.indexOf(cycle), pi = plan - 1;
  sumByCycle[ci] += s; belowByCycle[ci] += res.countBelow; glByCycle[ci] += res.countGridlock; nByCycle[ci] += res.nSim;
  sumByPlan[pi] += s; belowByPlan[pi] += res.countBelow; glByPlan[pi] += res.countGridlock; nByPlan[pi] += res.nSim;
  sumByOrder[order] += s; belowByOrder[order] += res.countBelow; glByOrder[order] += res.countGridlock; nByOrder[order] += res.nSim;
  if (res.best && (best === null || lessKey(res.best, best))) best = res.best;
}
function snapshot(final) {
  const elapsed = (Date.now() - t0) / 1000;
  const frac = done / TOTAL_TASKS;
  const eta = frac > 0 ? elapsed / frac - elapsed : 0;
  return {
    final: !!final, timestamp: new Date().toISOString(),
    tasksDone: done, tasksTotal: TOTAL_TASKS, nSimulated: nSim, configsTotalSpace: 18874368,
    elapsedSec: Math.round(elapsed), etaSec: Math.round(eta),
    baselineTTS: BASE, sumTTS: sumTTS.toString(),
    countBelowBaseline: countBelow, countGridlock,
    byCycle: CYC.map((c, i) => ({ cycle: c, n: nByCycle[i], sumTTS: sumByCycle[i].toString(), belowBaseline: belowByCycle[i], gridlock: glByCycle[i] })),
    byPlan: [0, 1, 2, 3, 4, 5].map(i => ({ plan: i + 1, n: nByPlan[i], sumTTS: sumByPlan[i].toString(), belowBaseline: belowByPlan[i], gridlock: glByPlan[i] })),
    byOrder: [0, 1].map(i => ({ order: i ? 'lag' : 'lead', n: nByOrder[i], sumTTS: sumByOrder[i].toString(), belowBaseline: belowByOrder[i], gridlock: glByOrder[i] })),
    best,
  };
}
let lastCkpt = 0;
function maybeCheckpoint(force) {
  const now = Date.now();
  if (force || now - lastCkpt > 15000) {
    lastCkpt = now;
    fs.writeFileSync(PROG + '.tmp', JSON.stringify(snapshot(false), null, 1));
    fs.renameSync(PROG + '.tmp', PROG);
    const s = snapshot(false);
    process.stdout.write(`[${s.elapsedSec}s] tasks ${done}/${TOTAL_TASKS} nSim=${nSim} below=${countBelow} gl=${countGridlock} best=${best ? best.total : '-'} eta=${Math.round(s.etaSec)}s\n`);
  }
}
function finish() {
  fs.writeFileSync(OUT, JSON.stringify(snapshot(true), null, 1));
  const s = snapshot(true);
  process.stdout.write('SWEEP DONE. nSim=' + nSim + ' sumTTS=' + sumTTS + ' below=' + countBelow + ' gridlock=' + countGridlock + '\n');
  process.stdout.write('best=' + JSON.stringify(best) + '\n');
  for (const w of workers) { try { w.send({ stop: true }); } catch (e) {} }
  setTimeout(() => process.exit(0), 200);
}

let nextTask = 0;
const workers = [];
function assign(w) {
  if (nextTask >= TOTAL_TASKS) { try { w.send({ stop: true }); } catch (e) {} return; }
  const task = tasks[nextTask++];
  w.send({ taskId: nextTask - 1, prog: task.prog, offStart: task.offStart, offEnd: task.offEnd, baseTTS: BASE });
}
process.stdout.write(`sweep: ${TOTAL_TASKS} tasks, ${NW} workers, chunk=${CHUNK}, progs [${PLO},${PHI})\n`);
for (let i = 0; i < NW; i++) {
  const w = fork(path.join(__dirname, 'simulator.js'), ['worker']);
  w.on('message', (m) => {
    if (m.ready) { assign(w); return; }
    if (m.done) {
      accumulate(m.res); done++;
      if (done === TOTAL_TASKS) { maybeCheckpoint(true); finish(); return; }
      maybeCheckpoint(false);
      assign(w);
    }
  });
  w.on('exit', (code) => { if (code && code !== 0 && done < TOTAL_TASKS) process.stderr.write('worker exited code ' + code + '\n'); });
  workers.push(w);
}

