const OFFLO = parseInt(process.env.OFFLO || '0'), OFFHI = parseInt(process.env.OFFHI || '262144');
const BASE = parseInt(process.env.BASE || '4052648');
const OUT = process.env.OUT || 'sweep_results.json';
const PROG = process.env.PROG || 'sweep_progress.json';
const TASKFILE = process.env.TASKS || 'sweep_tasks.jsonl';   // per-task results, for resume
const CYC = [60, 72, 84, 96, 108, 120];

function progDecode(prog) { return { cycle: CYC[(prog / 12) | 0], plan: ((prog >> 1) % 6) + 1, order: (prog & 1) }; }

// build tasks
const tasks = [];
for (let prog = PLO; prog < PHI; prog++)
  for (let o = OFFLO; o < OFFHI; o += CHUNK) tasks.push({ prog, offStart: o, offEnd: Math.min(o + CHUNK, OFFHI) });
const TOTAL_TASKS = tasks.length;

