    baselineTTS: BASE, sumTTS: sumTTS.toString(),
    countBelowBaseline: countBelow, countGridlock,
    byCycle: CYC.map((c, i) => ({ cycle: c, n: nByCycle[i], sumTTS: sumByCycle[i].toString(), belowBaseline: belowByCycle[i], gridlock: glByCycle[i] })),
