  fs.writeFileSync(OUT, JSON.stringify(snapshot(true), null, 1));
  process.stdout.write('SWEEP DONE. nSim=' + nSim + ' sumTTS=' + sumTTS + ' below=' + countBelow + ' gridlock=' + countGridlock + '\n');
