    if (!line) continue;
    let obj; try { obj = JSON.parse(line); } catch (e) { continue; }   // skip torn last line
    if (obj && obj.res && !doneSet.has(obj.taskId) && obj.taskId < TOTAL_TASKS) {
      doneSet.add(obj.taskId); accumulate(obj.res); done++;
    }
  }
