function assign(w) {
  const id = nextUndone();
  if (id >= TOTAL_TASKS) { try { w.send({ stop: true }); } catch (e) {} return; }
  nextTask++;
  const task = tasks[id];
  w.send({ taskId: id, prog: task.prog, offStart: task.offStart, offEnd: task.offEnd, baseTTS: BASE });
}
process.stdout.write(`sweep: ${TOTAL_TASKS} tasks, ${NW} workers, chunk=${CHUNK}, progs [${PLO},${PHI}), done=${doneSet.size}\n`);
for (let i = 0; i < NW; i++) {
  const w = fork(path.join(__dirname, 'simulator.js'), ['worker']);
  w.on('message', (m) => {
    if (m.ready) { assign(w); return; }
    if (m.done) {
      accumulate(m.res); done++;
      if (done === TOTAL_TASKS) { maybeCheckpoint(true); finish(); return; }
      maybeCheckpoint(false);
      assign(w);
    }
  });
  w.on('error', () => {});   // swallow IPC-channel-closed during shutdown
  w.on('exit', (code) => { if (code && code !== 0 && !finished && done < TOTAL_TASKS) process.stderr.write('worker exited code ' + code + '\n'); });
  workers.push(w);
}

